#include <bits/stdc++.h>
using namespace std;

#define LOOP(i, start, end) for(int i=start; i<=end; ++i)
#define REV_LOOP(i, start, end) for(int i=start; i>=end; --i)

typedef long long ll;

inline int read_value() {
    int x=0, sign=1; char c;
    while((c=getchar()) && (c<'0' || c>'9') && c!='-');
    if(c=='-') { sign=-1; c=getchar(); }
    do { x=(x*10)+(c^'0'); } while((c=getchar())>='0' && c<='9');
    return x*sign;
}

inline ll read_value_ll() {
    ll x=0; int s=1; char c;
    while((c=getchar()) && (c<'0' || c>'9') && c!='-');
    if(c=='-') { s=-1; c=getchar(); }
    do { x=(x*10)+(c^'0'); } while((c=getchar())>='0' && c<='9');
    return x*s;
}

const int MAXN=32, MOD=1000000007;

void add_modulo(int &x, int y) {
    x+=y; if(x>=MOD) x-=MOD;
}

struct Matrix {
    int mat[MAXN][MAXN];
    void clear() { memset(mat,0,sizeof(mat)); }
    void display() {
        LOOP(i,1,n+1) {
            LOOP(j,1,n+1) printf("%d%c", mat[i][j], j==n?'\n':' ');
        }
        putchar('\n');
    }
    Matrix operator*(const Matrix &rhs) const {
        Matrix res; res.clear();
        LOOP(i,1,n+1) LOOP(j,1,n+1) LOOP(k,1,n+1)
            add_modulo(res.mat[i][j], (ll)mat[i][k]*rhs.mat[k][j]%MOD);
        return res;
    }
};

int n;
Matrix identity, A[MAXN], pre[MAXN], suf[MAXN], result;

int main() {
#ifndef ONLINE_JUDGE
    freopen("matrix.in","r",stdin);
    freopen("matrix.out","w",stdout);
#endif
    ll m= read_value_ll(); n= read_value();
    memset(&identity,0,sizeof(identity));
    LOOP(i,1,n) identity.mat[i][i]=1;
    result=identity;
    LOOP(i,1,n) {
        A[i]=identity;
        A[i].mat[i][i]=1;
    }
    pre[0]=identity; suf[n+1]=identity;

    for(;m; m/=n) {
        ll u=m%n;
        if(u) {
            ll s=0, v=m/n;
            while(v) { s=(s+v%n)%n; v/=n; }
            u=(s+u-1)%n+1;
            for(; u!=s; --u) {
                if(u<=0) u+=n;
                result=A[u]*result;
            }
        }
        LOOP(i,1,n) pre[i]=pre[i-1]*A[i];
        for(int i=n; i>=1; --i) suf[i]=A[i]*suf[i+1];
        LOOP(i,1,n) A[i]=suf[i]*pre[i-1];
    }
    int res=1;
    LOOP(i,1,n) add_modulo(res, result.mat[n+1][i]);
    printf("%d\n", res);
    return 0;
}
